<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

long long getNumber() {
    long long num = 0;
    char c = getchar();
    while (c < 33) c = getchar();
    while (c > 33) {
        num = num * 10 + (c - '0');
        c = getchar();
    }
    return num;
}

int main() {
    long long index, x_val, y_val, total, numerator = 0, denominator = 1;
    x_val = getNumber();
    y_val = getNumber();
    total = getNumber();

    for (index = 1; index <= total; ++index) {
        long long p = x_val * index / y_val;
        long long q = p + 1;
        long long diff = index * (long long)fabs(x_val * denominator - numerator * y_val);
        long long t1 = denominator * (long long)fabs(x_val * index - y_val * p);
        long long t2 = denominator * (long long)fabs(x_val * index - y_val * q);
        if (t1 < diff) {
            numerator = p;
            denominator = index;
            diff = t1;
        }
        if (t2 < diff) {
            numerator = q;
            denominator = index;
            diff = t2;
        }
    }
    std::cout << numerator << "/" << denominator;
}
